<!DOCTYPE html><html lang="id"><head><meta charset="UTF-8"><title>Kuitansi Pembayaran</title><style>body{font-family:DejaVu Sans,sans-serif;color:#17201d;font-size:12px;padding:25px}.head{text-align:center;border-bottom:2px solid #17201d;padding-bottom:15px;margin-bottom:20px}h1{font-size:20px;margin:0 0 5px}.row{display:flex;justify-content:space-between;padding:9px 0;border-bottom:1px solid #ddd}.total{margin-top:18px;padding:14px;background:#f2f7e7;font-size:16px;font-weight:bold}.foot{margin-top:28px;color:#68736f;font-size:10px}</style></head><body><div class="head"><h1>ASRAMA PUTRI JUNJUNG BUYAH</h1><div>Kuitansi Pembayaran</div></div><div class="row"><strong>No. Kuitansi</strong><span>{{ $pembayaran->nomor_kuitansi }}</span></div><div class="row"><strong>Nama Penghuni</strong><span>{{ $pembayaran->user?->name }}</span></div><div class="row"><strong>Jenis Pembayaran</strong><span>{{ $pembayaran->jenis_pembayaran === 'registrasi' ? 'Uang Registrasi' : 'Iuran Bulanan' }}</span></div><div class="row"><strong>Periode</strong><span>{{ $pembayaran->bulan_tagihan }}/{{ $pembayaran->tahun_tagihan }}</span></div><div class="row"><strong>Metode</strong><span>{{ ucfirst($pembayaran->metode_pembayaran) }}</span></div><div class="total">Total: Rp {{ number_format($pembayaran->jumlah_bayar, 0, ',', '.') }}</div><div class="foot">Dicetak {{ now()->format('d-m-Y H:i') }} · {{ $settings['bank'] ?? '-' }} {{ $settings['nomor_rekening'] ?? '' }} a.n. {{ $settings['atas_nama'] ?? '-' }}</div></body></html>
